begin;
set local search_path=public,extensions;
select plan(18);
update auth.users set email_confirmed_at=now() where id in ('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000201');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
select is((public.list_managed_services('10000000-0000-4000-8000-000000000001','fictional','all','name','asc',5,0)->>'total')::integer,6,'service search is tenant scoped and searches safe text fields');
select is(jsonb_array_length(public.list_managed_services('10000000-0000-4000-8000-000000000001','','all','name','asc',5,0)->'items'),5,'service first page is bounded in the database');
select is(jsonb_array_length(public.list_managed_services('10000000-0000-4000-8000-000000000001','','all','name','asc',5,5)->'items'),1,'service second page is deterministic');
select is((public.list_managed_services('10000000-0000-4000-8000-000000000001','','archived','name','asc',5,0)->>'total')::integer,1,'archived service filtering is exact');
select is((public.list_owner_team_members('10000000-0000-4000-8000-000000000001','sage','all','all','name','asc',5,0)->>'total')::integer,1,'owner can search same-tenant member profile and authorized email projection');
select is((public.list_owner_team_members('10000000-0000-4000-8000-000000000001','','staff','inactive','status','asc',5,0)->>'total')::integer,1,'inactive staff filtering is exact');
select is((public.list_owner_invitations('10000000-0000-4000-8000-000000000001','pending.alpha','pending','email','asc',5,0)->>'total')::integer,1,'owner can search pending invitation history');
select is((public.list_schedule_members('10000000-0000-4000-8000-000000000001','sage','name','asc',5,0)->>'total')::integer,1,'owner lists eligible tenant schedules');
select throws_ok($$select public.list_managed_services('10000000-0000-4000-8000-000000000001','','all','unsafe','asc',5,0)$$,'22023','invalid list query','arbitrary service sort fields are rejected');
select throws_ok($$select public.list_managed_services('10000000-0000-4000-8000-000000000001','','all','name','asc',100,0)$$,'22023','invalid list window','unbounded page sizes are rejected');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","role":"authenticated"}',true);
select throws_ok($$select public.list_managed_services('10000000-0000-4000-8000-000000000001','','all','name','asc',5,0)$$,'42501','organization not found','staff cannot read owner service tooling');
select throws_ok($$select public.list_owner_team_members('10000000-0000-4000-8000-000000000001','','all','all','name','asc',5,0)$$,'42501','organization not found','staff cannot read owner team tooling');
select is((public.list_schedule_members('10000000-0000-4000-8000-000000000001','','name','asc',5,0)->>'total')::integer,1,'staff schedule list contains only self');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","role":"authenticated"}',true);
select throws_ok($$select public.list_managed_services('10000000-0000-4000-8000-000000000001','Movement','all','name','asc',5,0)$$,'42501','organization not found','cross-tenant service search fails closed');
select throws_ok($$select public.list_schedule_members('10000000-0000-4000-8000-000000000001','','name','asc',5,0)$$,'42501','schedules unavailable','cross-tenant schedule search fails closed');
select ok((select relrowsecurity from pg_class where oid='public.services'::regclass),'service RLS remains enabled');
select ok((select relrowsecurity from pg_class where oid='public.organization_invitations'::regclass),'invitation RLS remains enabled');
reset role;set local role anon;
select throws_ok($$select public.list_managed_services('10000000-0000-4000-8000-000000000001','','all','name','asc',5,0)$$,'42501',null,'anonymous users cannot execute list tooling');
select * from finish();rollback;
